from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny,nx))
                        q.append((ny,nx))
            by_row = {}
            for y, x in comp:
                by_row.setdefault(y, []).append(x)
            gaps = []
            for y, xs in by_row.items():
                left, right = min(xs), max(xs)
                gaps.extend((y, x) for x in range(left + 1, right) if grid[y][x] == bg)
            if gaps:
                fill = 2 if len(gaps) % 2 == 0 else 7
                for y, x in gaps:
                    out[y][x] = fill
    return out

